const {
  Document, Packer, Paragraph, TextRun, AlignmentType, PageBreak,
  BorderStyle, HeadingLevel, ExternalHyperlink,
} = require("docx");

const FONT = "Garamond";
const HEADLINE_FONT = "Amazon Ember";
const HEADLINE_COLOR = "1F5FA8"; // medium blue
const HEADLINE_SIZE = 30; // 15pt, in half-points

// Normalize straight apostrophes to a typographic right single quote so contractions/possessives
// match the curly dialogue quotes already used throughout, without hand-editing every string.
function sq(str) {
  if (typeof str !== "string") return str;
  return str.replace(/'/g, "’");
}

function P(text, opts = {}) {
  const {
    bold = false, italics = false, size = 24, align = AlignmentType.LEFT,
    spacingAfter = 200, spacingBefore = 0, border = false,
    font = FONT, color = undefined, heading = undefined,
  } = opts;
  const runs = Array.isArray(text)
    ? text.map(t => new TextRun({ text: sq(t.text), bold: t.bold ?? bold, italics: t.italics ?? italics, size: t.size ?? size, font: t.font ?? font, color: t.color ?? color }))
    : [new TextRun({ text: sq(text), bold, italics, size, font, color })];
  const pOpts = {
    children: runs,
    alignment: align,
    spacing: { after: spacingAfter, before: spacingBefore },
  };
  if (border) {
    pOpts.border = { bottom: { color: "888888", space: 4, style: BorderStyle.SINGLE, size: 6 } };
  }
  if (heading) {
    pOpts.heading = heading;
  }
  return new Paragraph(pOpts);
}

// Headline style per spec: Amazon Ember, bold, 15pt, medium blue, centered.
// Tagged with a real Word heading level so Kindle/KDP conversion can build a working TOC from it.
function headline(text, opts = {}) {
  const { heading = HeadingLevel.HEADING_1, spacingAfter = 300, spacingBefore = 0, border = false } = opts;
  return P(text, {
    bold: true, font: HEADLINE_FONT, color: HEADLINE_COLOR, size: HEADLINE_SIZE,
    align: AlignmentType.CENTER, spacingAfter, spacingBefore, heading, border,
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function body(paras) {
  return paras.map(t => P(t, { size: 24, align: AlignmentType.JUSTIFIED, spacingAfter: 200 }));
}

function chapterHeading(numeral, title) {
  return [
    P(`Chapter ${numeral}`, { italics: true, align: AlignmentType.CENTER, size: 22, spacingAfter: 60, spacingBefore: 400 }),
    headline(title, { heading: HeadingLevel.HEADING_1, spacingAfter: 200 }),
  ];
}

function guideQuote(text, attribution) {
  return [
    P(text, { italics: true, align: AlignmentType.CENTER, size: 20, spacingBefore: 0, spacingAfter: 40 }),
    P(attribution, { italics: true, align: AlignmentType.CENTER, size: 18, spacingAfter: 320 }),
  ];
}

function bookHeading(label, title, subtitle) {
  return [
    pageBreak(),
    headline(label, { heading: HeadingLevel.HEADING_1, spacingBefore: 800, spacingAfter: 80 }),
    headline(title, { heading: HeadingLevel.HEADING_2, spacingAfter: 120 }),
    P(subtitle, { italics: true, align: AlignmentType.CENTER, size: 24, spacingAfter: 400 }),
  ];
}

function castEntry(name, desc) {
  return P([{ text: name + " \u2014 ", bold: true }, { text: desc, bold: false }], { size: 23, spacingAfter: 160, align: AlignmentType.JUSTIFIED });
}

// Builds a paragraph from mixed segments: plain strings render as body text; {text, url} segments
// render as a real clickable hyperlink anchored to that phrase, never as visible raw URL text.
function sourceNote(segments, opts = {}) {
  const { size = 23, spacingAfter = 200, align = AlignmentType.JUSTIFIED } = opts;
  const children = segments.map(seg => {
    if (typeof seg === "string") {
      return new TextRun({ text: sq(seg), size, font: FONT });
    }
    return new ExternalHyperlink({
      link: seg.url,
      children: [new TextRun({ text: sq(seg.text), size, font: FONT, style: "Hyperlink", color: "1155CC", underline: {} })],
    });
  });
  return new Paragraph({ children, alignment: align, spacing: { after: spacingAfter } });
}

